SELECT DATE_TRUNC('MONTH', start_date) AS activity_month, CASE WHEN monthly_fee >= 267 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, MAX(monthly_fee) FILTER (WHERE plan = 'standard') AS standard_max_monthly_fee, COUNT(*) FILTER (WHERE plan = 'standard') AS standard_rows, SIZE(COLLECT_SET(plan)) AS num_plans, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(*) AS row_count FROM subscriptions GROUP BY 1, 2 ORDER BY row_count
